	(17, '82664709', 'Enchufe schuko LEXMAN Trail IP55 color antracita', 'enchufe-schuko-lexman-trail-ip55-color-antracita-f4ccd3', 1, 5, 4.02, 21.0, 119, 'basic', 0, 'Enchufe Lexman Trail fabricado en plástico de color antracita brillante. Cuenta con tapa y 1 módulo. Gracias a su IP55, está especialmente indicado para instalar en zonas exteriores, como un balcón, una terraza o un porche. Dispone de 250 V de tensión, 4.000 W de potencia y 16 A de intensidad. Se fija mediante atornillado. Ofrece 5 años de garantía. Medidas: 8 x 5,9 x 8 cm (ancho x alto x largo).', '{"Nombre de la serie": "Trail", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo | Garras de fijación", "Altura (en mm)": "59", "Anchura (en mm)": "80", "Profundidad (en mm)": "80", "Marca del producto": "LEXMAN", "Material principal en la masa total del producto": "Polipropileno", "Garantía (en años)": "5", "Producto empaquetado: anchura (en cm)": "8", "Producto empaquetado: altura (en cm)": "5.9", "Producto empaquetado: profundidad (en cm)": "8", "Producto empaquetado: peso (en kg)": "0.13", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/enchufe-schuko-lexman-trail-ip55-color-antracita-82664709.html", "_images": ["/assets/img/productos/82664709.png", "/assets/img/productos/82664709_1.png", "/assets/img/productos/82664709_2.png", "/assets/img/productos/82664709_3.png", "/assets/img/productos/82664709_4.png", "/assets/img/productos/82664709_5.png", "/assets/img/productos/82664709_6.png", "/assets/img/productos/82664709_7.png", "/assets/img/productos/82664709_8.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4262409/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3283028/media.pdf", "size": null, "mime": "application/pdf", "source_host"