	(25, '85218287', 'Interruptor LEXMAN Trail IP55 color blanco', 'interruptor-lexman-trail-ip55-color-blanco-d705e2', 1, 5, 5.35, 21.0, 146, 'basic', 0, 'Enchufe Lexman Trail fabricado en plástico de color beige. Gracias a su IP55, está especialmente indicado para instalar en zonas exteriores, como un balcón, una terraza o un porche. Dispone de 250 V de tensión, 2.500 W de potencia y 10 A de intensidad. Se fija mediante atornillado. Ofrece 5 años de garantía. Medidas: 8 x 5,8 x 8 cm (ancho x alto x largo).', '{"Nombre de la serie": "Trail", "Tipo de producto": "Interruptor conmutador", "Marca del producto": "LEXMAN", "Familia de color": "Beige", "Acabado del producto": "Liso", "Tipo de fijación": "Tornillo", "Anchura (en mm)": "80", "Altura (en mm)": "58", "Objeto conectado (domótica y smarthome)": "No", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "8", "Producto empaquetado: altura (en cm)": "5.7", "Producto empaquetado: profundidad (en cm)": "8", "Producto empaquetado: peso (en kg)": "0.126", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/interruptor-lexman-trail-ip55-color-blanco-85218287.html", "_images": ["/assets/img/productos/85218287.png", "/assets/img/productos/85218287_1.png", "/assets/img/productos/85218287_2.png", "/assets/img/productos/85218287_3.png", "/assets/img/productos/85218287_4.png", "/assets/img/productos/85218287_5.png", "/assets/img/productos/85218287_6.png", "/assets/img/productos/85218287_7.png", "/assets/img/productos/85218287_8.png", "/assets/img/productos/85218287_9.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4267070/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3283023/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}'