	(26, '82664707', 'Pulsador con luz LEXMAN Trail IP55 color antracita', 'pulsador-con-luz-lexman-trail-ip55-color-antracita-0d6fdf', 1, 5, 7.9, 21.0, 107, 'basic', 0, 'Pulsador Lexman Trail fabricado en plástico de color antracita. Incorpora una luz indicadora. Gracias a su IP55, está especialmente indicado para instalar en zonas exteriores, como un balcón, una terraza o un porche. Dispone de 250 V de tensión y 10 A de intensidad. Se fija mediante atornillado. Ofrece 5 años de garantía. Medidas: 8 x 5,8 x 8 cm (ancho x alto x largo).', '{"Nombre de la serie": "Trail", "Tipo de producto": "Interruptor de pulsador", "Marca del producto": "LEXMAN", "Familia de color": "Gris / plata", "Acabado del producto": "Liso", "Tipo de fijación": "Tornillo | Garras de fijación", "Anchura (en mm)": "80", "Altura (en mm)": "58", "Objeto conectado (domótica y smarthome)": "No", "Garantía (en años)": "5", "Producto empaquetado: anchura (en cm)": "8", "Producto empaquetado: altura (en cm)": "5.7", "Producto empaquetado: profundidad (en cm)": "8", "Producto empaquetado: peso (en kg)": "0.12", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/pulsador-con-luz-lexman-trail-ip55-color-antracita-82664707.html", "_images": ["/assets/img/productos/82664707.png", "/assets/img/productos/82664707_1.png", "/assets/img/productos/82664707_2.png", "/assets/img/productos/82664707_3.png", "/assets/img/productos/82664707_4.png", "/assets/img/productos/82664707_5.png", "/assets/img/productos/82664707_6.png", "/assets/img/productos/82664707_7.png", "/assets/img/productos/82664707_8.png", "/assets/img/productos/82664707_9.png", "/assets/img/productos/82664707_10.png", "/assets/img/productos/82664707_11.png", "/assets/img/productos/82664707_12.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4267073/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "