	(27, '81896311', 'Enchufe doble gris BRICOFONTINI BF-17', 'enchufe-doble-gris-bricofontini-bf-17-d03a84', 1, 6, 6.79, 21.0, 68, 'basic', 0, 'Enchufe con acabado en color gris, que permite enchufar aparatos eléctricos con toma de tierra de hasta 16 amperios. Su alto grado de protección (IP54) lo hace ideal para su instalación en exterior. Medidas: 56 x 143 x 145 mm(ancho x alto x profundidad).', '{"Nombre de la serie": "BF-17", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo", "Altura (en mm)": "56", "Anchura (en mm)": "143", "Profundidad (en mm)": "145", "Marca del producto": "BRICO FONTINI", "Modelo comercial": "17219092", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "7", "Producto empaquetado: altura (en cm)": "5", "Producto empaquetado: profundidad (en cm)": "14.5", "Producto empaquetado: peso (en kg)": "0.17", "Marca": "BRICO FONTINI", "_source": "https://www.leroymerlin.es/productos/enchufe-doble-gris-bricofontini-bf-17-81896311.html", "_images": ["/assets/img/productos/81896311.png", "/assets/img/productos/81896311_1.png", "/assets/img/productos/81896311_2.png", "/assets/img/productos/81896311_3.png"]}', '2026-05-06 19:16:46', '/assets/img/productos/81896311.png'),
	(28, '82603343', 'Enchufe doble de superficie LEXMAN de 16A', 'enchufe-doble-de-superficie-lexman-de-16a-69e085', 1, 5, 5.95, 21.0, 57, 'basic', 0, 'Enchufe rectangular Lexman Surface fabricado en plástico de color blanco. Ofrece 2 tomas, 250 V de tensión y un índice de protección IP20. Con él podrás enchufar aparatos eléctricos de hasta 16 amperios. Se fija fácilmente mediante atornillado. Medidas: 122 x 70 mm (ancho x alto).', '{"Nombre de la serie": "Surface", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo | Garras de fijación", "Altura (en mm)": "40", "Anchura (en mm)": "70", "Profundidad (en mm)": "122", "Marca del producto": "LEXMAN", "Modelo comercial": "Surface", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "5", "Producto empaquetado: anchura (en cm)": "7", "Producto empaquetado: altura (en cm)": "4", "Producto empaquetado: profundidad (en cm)": "12.2", "Producto empaquetado: peso (en kg)": "0.122", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/enchufe-doble-de-superficie-lexman-de-16a-82603343.html", "_images": ["/assets/img/productos/82603343.png", "/assets/img/productos/82603343_1.png", "/assets/img/productos/82603343_2.png", "/assets/img/productos/82603343_3.png", "/assets/img/productos/82603343_4.png", "/assets/img/productos/82603343_5.png", "/assets/img/productos/82603343_6.png", "/assets/img/productos/82603343_7.jpeg"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/1762521/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 19:16:46', '/assets/img/productos/82603343.png'),
	(29, '82277550', 'Enchufe monoblock doble LIKA color blanco', 'enchufe-monoblock-doble-lika-color-blanco-f2fe07', 1, 5, 6.05, 21.0, 143, 'basic', 0, 'Enchufe monoblock doble Lexman, fabricado en plástico, para conectar cualquier dispositivo a la red eléctrica. Tiene un acabado en color blanco y lo podrás combinar con otros productos de la serie Lika, disponibles en Leroy Merlin, que permiten distintas soluciones para el hogar. Medidas: 8,2 x 4,3 x 12,3 cm (ancho x alto x fondo).', '{"Nombre de la serie": "Lika", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo | Garras de fijación", "Altura (en mm)": "43", "Anchura (en mm)": "82", "Profundidad (en mm)": "123", "Marca del producto": "LEXMAN", "Modelo comercial": "Lika", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "5", "Producto empaquetado: anchura (en cm)": "10", "Producto empaquetado: altura (en cm)": "4", "Producto empaquetado: profundidad (en cm)": "11.8", "Producto empaquetado: peso (en kg)": "0.11", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/enchufe-monoblock-doble-lika-color-blanco-82277550.html", "_images": ["/assets/img/productos/82277550.png", "/assets/img/productos/82277550_1.png", "/assets/img/productos/82277550_2.png", "/assets/img/productos/82277550_3.png", "/assets/img/productos/82277550_4.png", "/assets/img/productos/82277550_5.png", "/assets/img/productos/82277550_6.jpeg", "/assets/img/productos/82277550_7.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/1763285/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/1762024/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 19:16:46', '/assets/img/productos/82277550.png'),
	(30, '10004813', 'Enchufe doble BRICOFONTINI Kristal blanco de 16a 250v', 'enchufe-doble-bricofontini-kristal-blanco-de-16a-250v-c90609', 1, 6, 7.49, 21.0, 81, 'basic', 0, 'Enchufe doble de 16 A ideal para conectar a la red eléctrica varios dispositivos de forma simultánea usando la misma toma. Está fabricado en plástico de color blanco mate. Lo podrás combinar con otros elementos de la serie Kristal disponible en Leroy Merlin y crear un ambiente a tu gusto en tus habitaciones. Cuenta con un sistema de seguridad infantil para evitar accidentes de los más pequeños. Medidas: 80 x 117 mm (ancho x largo).', '{"Nombre de la serie": "Kristal", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo", "Altura (en mm)": "127", "Anchura (en mm)": "80", "Profundidad (en mm)": "39", "Marca del producto": "BRICO FONTINI", "Modelo comercial": "20219052", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "12.7", "Producto empaquetado: altura (en cm)": "8", "Producto empaquetado: profundidad (en cm)": "3.9", "Producto empaquetado: peso (en kg)": "0.104", "Marca": "BRICO FONTINI", "_source": "https://www.leroymerlin.es/productos/enchufe-doble-bricofontini-kristal-blanco-de-16a-250v-10004813.html", "_images": ["/assets/img/productos/10004813.jpg", "/assets/img/productos/10004813_1.jpg", "/assets/img/productos/10004813_2.jpg"]}', '2026-05-06 19:16:47', '/assets/img/productos/10004813.jpg'),
	(31, '81950540', 'Enchufe doble LEGRAND Niloé Step blanco', 'enchufe-doble-legrand-niloe-step-blanco-95d500', 1, 7, 10.29, 21.0, 92, 'basic', 0, 'Enchufe doble con toma de tierra, fabricado en plástico resistente blanco mate, con una intensidad de 16 amperios. Perfecto para instalar 2 funciones, cuenta con sistema de seguridad infantil y se fija fácilmente a la pared gracias a su sistema en 2 pasos. Podrás combinar su diseño con el resto de interruptores y enchufes de la serie Niloé de Legrand, disponibles en Leroy Merlin. Esta serie mezcla hasta 6 acabados diferentes con las funciones imprescindibles para nuevas obras o la renovación eléctrica de tu hogar. Medidas: 12 x 18 x 6 cm (ancho x alto x profundo).', '{"Nombre de la serie": "Niloé", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Garras de fijación", "Altura (en mm)": "180", "Anchura (en mm)": "120", "Profundidad (en mm)": "60", "Marca del producto": "LEGRAND", "Modelo comercial": "Niloé Step", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "16", "Producto empaquetado: altura (en cm)": "6", "Producto empaquetado: profundidad (en cm)": "11", "Producto empaquetado: peso (en kg)": "0.1", "Marca": "LEGRAND", "_source": "https://www.leroymerlin.es/productos/enchufe-doble-legrand-niloe-step-blanco-81950540.html", "_images": ["/assets/img/productos/81950540.png", "/assets/img/productos/81950540_1.png", "/assets/img/productos/81950540_2.png", "/assets/img/productos/81950540_3.png", "/assets/img/productos/81950540_4.png", "/assets/img/productos/81950540_5.png", "/assets/img/productos/81950540_6.png", "/assets/img/productos/81950540_7.png", "/assets/img/productos/81950540_8.png", "/assets/img/productos/81950540_9.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/2567980/media.pdf", "size": null, "mime": "application/pdf", "source_ho