	(37, '17377283', 'Enchufe doble LEGRAND Forix blanco', 'enchufe-doble-legrand-forix-blanco-edbcf4', 1, 7, 8.29, 21.0, 54, 'basic', 0, 'Base de corriente con dos pulsadores con acabado en color blanco mate. Dispone de función doble que permite enchufar aparatos eléctricos con toma de tierra de hasta 16 amperios. Medidas: 110 x 65 x 38 mm (ancho x alto x profundidad).', '{"Nombre de la serie": "Forix", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo", "Altura (en mm)": "110", "Anchura (en mm)": "65", "Profundidad (en mm)": "38", "Marca del producto": "LEGRAND", "Modelo comercial": "Forix", "Material principal en la masa total del producto": "Polipropileno", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "10.9", "Producto empaquetado: altura (en cm)": "18", "Producto empaquetado: profundidad (en cm)": "3.8", "Producto empaquetado: peso (en kg)": "0.094", "Marca": "LEGRAND", "_source": "https://www.leroymerlin.es/productos/enchufe-doble-legrand-forix-blanco-17377283.html", "_images": ["/assets/img/productos/17377283.jpg", "/assets/img/productos/17377283_1.png", "/assets/img/productos/17377283_2.png", "/assets/img/productos/17377283_3.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4815431/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 19:16:54', '/assets/img/productos/17377283.jpg'),
	(38, '82277582', 'Cargador con 2 USB LIKA color blanco', 'cargador-con-2-usb-lika-color-blanco-ececa4', 1, 5, 13.45, 21.0, 126, 'basic', 0, 'Cargador con 2 puertos USB Lexman, fabricado en plástico, con un acabado en color blanco. Podrás combinarlo con otros productos de la serie Lika, disponibles en Leroy Merlin, que permiten distintas soluciones para el hogar. Medidas: 8,2 x 5,4 x 8,2 cm (ancho x alto x fondo).', '{"Nombre de la serie": "Lika", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo | Garras de fijación", "Altura (en mm)": "54", "Anchura (en mm)": "82", "Profundidad (en mm)": "82", "Marca del producto": "LEXMAN", "Modelo comercial": "Lika", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "5", "Producto empaquetado: anchura (en cm)": "8.8", "Producto empaquetado: altura (en cm)": "4", "Producto empaquetado: profundidad (en cm)": "9", "Producto empaquetado: peso (en kg)": "0.1", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/cargador-con-2-usb-lika-color-blanco-82277582.html", "_images": ["/assets/img/productos/82277582.png", "/assets/img/productos/82277582_1.png", "/assets/img/productos/82277582_2.png", "/assets/img/productos/82277582_3.png", "/assets/img/productos/82277582_4.png", "/assets/img/productos/82277582_5.png", "/assets/img/productos/82277582_6.png", "/assets/img/productos/82277582_7.png", "/assets/img/productos/82277582_8.png", "/assets/img/productos/82277582_9.jpg", "/assets/img/productos/82277582_10.jpeg", "/assets/img/productos/82277582_11.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3795867/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3699422/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.ler