	(39, '85089391', 'Toma USB-A + USB-C LEXMAN Luxia color blanco', 'toma-usb-a-usb-c-lexman-luxia-color-blanco-30bab7', 1, 5, 19.99, 21.0, 27, 'basic', 0, 'Toma USB-A + USB-C Lexman Luxia fabricada en plástico de color blanco. De forma cuadrada, cuenta con 1 módulo. También dispone de IK04, IP20 (recomendado para espacios interiores en los que la iluminación no se vea expuesta a factores externos peligrosos), 3 A de intensidad y 240 V de tensión. Cumple una función de USB. Se coloca empotrada. Producto fabricado en la Unión Europea con 5 años de garantía. Disponible en varios colores. Medidas: 73,95 x 73,95 x 41,7 mm (ancho x alto x fondo).', '{"Nombre de la serie": "Luxia", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo", "Altura (en mm)": "73.95", "Anchura (en mm)": "73.95", "Profundidad (en mm)": "41.7", "Marca del producto": "LEXMAN", "Material principal en la masa total del producto": "PVC", "Garantía (en años)": "5", "Producto empaquetado: anchura (en cm)": "9.2", "Producto empaquetado: altura (en cm)": "5", "Producto empaquetado: profundidad (en cm)": "15", "Producto empaquetado: peso (en kg)": "0.086", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/toma-usb-a-usb-c-lexman-luxia-color-blanco-85089391.html", "_images": ["/assets/img/productos/85089391.png", "/assets/img/productos/85089391_1.png", "/assets/img/productos/85089391_2.png", "/assets/img/productos/85089391_3.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3458485/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 19:16:55', '/assets/img/productos/85089391.png'),
