	(49, '84372276', 'Bombilla Inteligente LED E27 806 lúmenes 7W CCT 2200K-6500K CRI 89-80 luz natural y fiel clase energética E', 'bombilla-inteligente-led-e27-806-lumenes-7w-cct-2200k-6500k-cri-89-80-luz-natural-y-fiel-clase-energ-2caeb5', 2, 5, 12.99, 21.0, 9, 'basic', 0, 'Bombilla Lexman de forma Edison. Fabricada en cristal de color ámbar, cuenta con una potencia de 7 W y casquillo E27. Su tecnología led aporta una luz que oscila del color blanco cálido al blanco frío entre 2.700 K y 6.500 K y un flujo luminoso de 806 lúmenes de intensidad. Con un tipo de encendido instantáneo, cuenta con un ángulo de iluminación de 320º. Tiene una vida útil de hasta 15.000 horas. Dispone de conexión wifi y Bluetooth. El dispositivo puede ser controlado mediante interruptor, mando a distancia y Smartphone. Clase de eficiencia energética E. Cuenta con una garantía de 3 años.', '{"Número de unidades consumidor": "1", "Intensidad luminosa (en lumen)": "806", "Tipo de casquillo": "E27", "Tipo de producto": "Bombilla", "Tipo de bombilla": "Inteligente", "Índice de protección (IP)": "IP00", "Potencia (en W)": "7", "Temperatura de color (en K)": "De 2200 a 6500", "Variación de la intensidad de la luz": "Sí", "Color de la luz ajustable": "Sí", "Objeto conectado (domótica y smarthome)": "Sí", "Vida útil (en h)": "15000", "Haz de la bombilla (ángulo) (en °)": "320", "Acabado del vidrio": "Ámbar", "Compatible con variador": "No", "Material principal en la masa total del producto": "Vidrio", "Garantía (en años)": "5", "Clase energética (A a G)": "E", "Marca del producto": "LEXMAN", "Batería incluida": "No", "Mando a distancia incluido": "No", "Índice de reproducción cromática (IRC)": "De 80 a 89", "Tipo de protocolo wifi": "Bluetooth Zigbee", "Alimentación": "Red eléctrica", "Con luz ultravioleta (UV)": "No", "Especificidad del producto": "Control de la intensidad de la luz", "Tipo de tecnología de la bombilla": "LED", "Producto empaquetado: anchura (en cm)": "7.2", "Producto empaquetado: altura (en cm)": "17.4", "Producto empaquetado: profundidad (en cm)": "6.7", "Producto empaquetado: peso (en kg)": "0.09", "Marca": "LEXMAN", "_source": "https://www.leroymerlin.es/productos/bombilla-inteligente-led-e27-806-lumenes-7w-cct-2200k-6500k-cri-89-80-luz-natural-y-fiel-clase-energetica-e-84372276.html", "_images": ["/assets/img/productos/84372276.png", "/assets/img/productos/84372276_1.png", "/assets/img/productos/84372276_2.png", "/assets/img/productos/84372276_3.png", "/assets/img/productos/84372276_4.png", "/assets/img/productos/84372276_5.jpeg", "/assets/img/productos/84372276_6.jpeg"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/2666789/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/2709084/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/1673577/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones con DoC firmado", "url": "https://media.adeo.com/media/1627161/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 19:17:04', '/assets/img/productos/84372276.png'),
