	(91, '15395695', 'Limitador sobretensiones permanentes y transitorias F+N 40A', 'limitador-sobretensiones-permanentes-y-transitorias-fn-40a-01ee91', 4, 8, 111.0, 21.0, 9, 'basic', 0, 'Limitador de sobretensiones permanentes y transitorias indicado para proteger las instalaciones eléctricas y los equipos electrónicos hasta 25 amperios. Su uso es ideal para prevenir posibles problemas derivados de la cercanía a centros comerciales, fábricas, redes de alta tensión, etc.', '{"Tipo de producto": "Para rayo", "Marca del producto": "SCHNEIDER ELECTRIC", "Producto empaquetado: anchura (en cm)": "10", "Producto empaquetado: altura (en cm)": "8.5", "Producto empaquetado: profundidad (en cm)": "11", "Producto empaquetado: peso (en kg)": "0.55", "Subcategoría": "Sobretensiones", "Gama": "SPU", "Intensidad nominal (A)": "40A", "_extra_intensidad": "40A", "_source": "https://www.leroymerlin.es/productos/limitador-sobretensiones-permanentes-y-transitorias-f-n-40a-15395695.html", "_images": ["/assets/img/productos/15395695.png", "/assets/img/productos/15395695_1.png", "/assets/img/productos/15395695_2.png", "/assets/img/productos/15395695_3.png", "/assets/img/productos/15395695_4.png"], "_variant_group": "schneider-electric-spu-sobretensiones-by-intensidad", "_variant_axis": "Intensidad", "_variant_default": "15395681", "_variant_is_default": "0", "_variant_label": "40A", "_variants": [{"sku": "15395681", "label": "25A", "price": 101.0}, {"sku": "15395695", "label": "40A", "price": 111.0}]}', '2026-05-06 19:23:21', '/assets/img/productos/15395695.png'),
