	(253, '82472325', 'Plafón LED 40W 2400lm 33cm de diámetro', 'plafon-led-40w-2400lm-33cm-de-diametro-63d86e', 3, 54, 21.99, 21.0, 20, 'basic', 0, 'Plafón led de 40 W de potencia. Es ultrafino, con tono e intensidad regulables, 2400 lúmenes, mando y 33 cm de diámetro. Este producto mejora el confort térmico y ayuda a alcanzar un ahorro de energía igual o superior al 60%. Garantía 3 años', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "De 2700 a 5000", "Variación de la intensidad de la luz": "Sí", "Color de la luz ajustable": "No", "Familia de color": "Blanco", "Aspecto": "Mate", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "Sí", "Ángulo del haz de luz (en °)": "120", "Altura (en cm)": "5.5", "Anchura (en cm)": "33", "Diámetro (en cm)": "33", "Peso neto (en kg)": "0.58", "Garantía (en años)": "5", "Clase energética (A a G)": "F", "Marca del producto": "MANTRA", "Producto empaquetado: anchura (en cm)": "37.5", "Producto empaquetado: altura (en cm)": "7", "Producto empaquetado: profundidad (en cm)": "37.5", "Producto empaquetado: peso (en kg)": "0.8", "Marca": "MANTRA", "_source": "https://www.leroymerlin.es/productos/plafon-led-40w-2400lm-33cm-de-diametro-82472325.html", "_images": ["/assets/img/productos/82472325.jpg", "/assets/img/productos/82472325_1.jpg", "/assets/img/productos/82472325_2.jpg", "/assets/img/productos/82472325_3.jpg", "/assets/img/productos/82472325_4.jpg", "/assets/img/productos/82472325_5.jpg", "/assets/img/productos/82472325_6.png", "/assets/img/productos/82472325_7.jpg", "/assets/img/productos/82472325_8.jpg", "/assets/img/productos/82472325_9.png"]}', '2026-05-06 22:42:09', '/assets/img/productos/82472325.jpg'),
	(254, '93040914', 'Plafón redondo 1 luz E27 de acero negro INSPIRE Mikona ø28 cm', 'plafon-redondo-1-luz-e27-de-acero-negro-inspire-mikona-28-cm-6aef9c', 2, 51, 29.99, 21.0, 6, 'basic', 0, 'La lámpara de techo Inspire Mikona, con su acabado natural y 28 cm de diámetro, es perfecta para iluminar cualquier estancia. Fabricada en ratán tejido, esta lámpara de techo irradia un estilo bohemio y chic que complementa interiores modernos. Su estructura tejida proyecta un hermoso efecto de sombra y luz, realzando sutilmente el techo. La elección de la bombilla puede influir enormemente en la atmósfera de su espacio. Opte por una bombilla de color cálido para una luz acogedora y atractiva, perfecta para ambientes relajantes. Como alternativa, una bombilla de color frío puede crear una luz más dinámica y energizante, ideal para crear una atmósfera activa y vibrante. Recomendamos una bombilla decorativa transparente E27 para un mayor atractivo estético. Para una apariencia cohesiva, puede combinar esta lámpara de techo con otros productos de la serie Mikona. Este producto cuenta con una garantía de 5 años, lo que garantiza su calidad y durabilidad.', '{"Tipo de casquillo": "E27", "Cantidad de luces": "1", "Familia de color": "Beige", "Aspecto": "Mate", "Estilo internacional": "Bohème", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Altura (en cm)": "19", "Anchura (en cm)": "28", "Diámetro (en cm)": "28", "Peso neto (en kg)": "0.55", "Garantía (en años)": "5", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "29", "Producto empaquetado: altura (en cm)": "17.5", "Producto empaquetado: profundidad (en cm)": "29", "Producto empaquetado: peso (en kg)": "0.76", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-redondo-1-luz-e27-de-acero-negro-inspire-mikona-28-cm-93040914.html", "_images": ["/assets/img/productos/93040914.png", "/assets/img/productos/93040914_1.png", "/assets/img/productos/93040914_2.png", "/assets/img/productos/93040914_3.png", "/assets/img/productos/93040914_4.png", "/assets/img/productos/93040914_5.png", "/assets/img/productos/93040914_6.png", "/assets/img/productos/93040914_7.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4692266/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4692254/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 22:42:13', '/assets/img/productos/93040914.png'),
	(255, '91242445', 'Plafón LED de interior redondo negro INSPIRE Drema 2500 lm blanco neutro ø32 cm', 'plafon-led-de-interior-redondo-negro-inspire-drema-2500-lm-blanco-neutro-32-cm-9a5067', 2, 51, 29.99, 21.0, 127, 'basic', 0, 'Plafón Inspire Drema fabricado en policarbonato y polipropileno con forma redonda y acabado de color negro. Cuenta con 1 luz, índice de protección IP44, 2500 lúmenes de flujo luminoso y 2700-4000 K de temperatura de color regulable. Este producto es reparable y tiene una garantía de 5 años; ponte en contacto con el servicio posventa de tu tienda para obtener más detalles. Disponible en varios acabados. Medidas: 32 x 5 x 32 cm (ancho x alto x fondo).', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "2700 | 4000", "Variación de la intensidad de la luz": "No", "Color de la luz ajustable": "Sí", "Familia de color": "Negro", "Aspecto": "Satinado", "Estilo internacional": "Essential", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Ángulo del haz de luz (en °)": "120", "Altura (en cm)": "5", "Anchura (en cm)": "32", "Diámetro (en cm)": "32", "Peso neto (en kg)": "0.9", "Garantía (en años)": "5", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "33", "Producto empaquetado: altura (en cm)": "6", "Producto empaquetado: profundidad (en cm)": "33", "Producto empaquetado: peso (en kg)": "1.03", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-led-de-interior-redondo-negro-inspire-drema-2500-lm-blanco-neutro-32-cm-91242445.html", "_images": ["/assets/img/productos/91242445.png", "/assets/img/productos/91242445_1.png", "/assets/img/productos/91242445_2.jpg", "/assets/img/productos/91242445_3.png", "/assets/img/productos/91242445_4.png", "/assets/img/productos/91242445_5.png", "/assets/img/productos/91242445_6.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4386994/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4442826/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 22:42:17', '/assets/img/productos/91242445.png'),
	(256, '84659841', 'Plafón de exterior e interior INSPIRE Shinrin 1200lm 4000K madera', 'plafon-de-exterior-e-interior-inspire-shinrin-1200lm-4000k-madera-59e3b7', 2, 51, 19.99, 21.0, 49, 'basic', 0, 'Plafón para exterior Inspire modelo Shinrin, de forma circular, fabricado en plástico con acabado en color marrón imitación madera. Cuenta con una potencia de 16 W. Su tecnología de led integrado aporta una luz blanca neutra de 4.000 K y un flujo luminoso de 2.100 lúmenes. Índice de protección IP44 (resistente a salpicaduras de agua). Tiene una vida útil de 25.920 horas. 5 años de garantía. Etiqueta energética: E. Medidas: 30 x 5 cm (diámetro x alto).', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "4000", "Variación de la intensidad de la luz": "No", "Color de la luz ajustable": "No", "Familia de color": "Marrón", "Aspecto": "Mate", "Estilo internacional": "Nature", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Altura (en cm)": "5", "Anchura (en cm)": "30", "Diámetro (en cm)": "30", "Peso neto (en kg)": "0.79", "Garantía (en años)": "5", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "6", "Producto empaquetado: altura (en cm)": "31.5", "Producto empaquetado: profundidad (en cm)": "31", "Producto empaquetado: peso (en kg)": "0.93", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-de-exterior-e-interior-inspire-shinrin-1200lm-4000k-madera-84659841.html", "_images": ["/assets/img/productos/84659841.png", "/assets/img/productos/84659841_1.png", "/assets/img/productos/84659841_2.png", "/assets/img/productos/84659841_3.png", "/assets/img/productos/84659841_4.jpg", "/assets/img/productos/84659841_5.png", "/assets/img/productos/84659841_6.jpg"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4100525/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.e