	(257, '97518316', 'Plafón LED redondo blanco MANTRA 3850 lm blanco neutro ø40 cm IP20', 'plafon-led-redondo-blanco-mantra-3850-lm-blanco-neutro-40-cm-ip20-c26a54', 2, 54, 44.99, 21.0, 54, 'basic', 0, 'Plafón de techo LED DOBLE fabricado en ABS, acabado en blanco de 40cm de diámetro. Luz LED de 3850lm (360º), una potencia de 36W y temperatura de 4000K (blanco cálido). Ideal para iluminar espacios interiores (índice de protección IP20). Garantía de 5 años', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "4000", "Variación de la intensidad de la luz": "No", "Color de la luz ajustable": "No", "Familia de color": "Blanco", "Aspecto": "Mate", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Altura (en cm)": "3.5", "Anchura (en cm)": "40", "Diámetro (en cm)": "40", "Peso neto (en kg)": "1.25", "Garantía (en años)": "5", "Marca del producto": "MANTRA", "Producto empaquetado: anchura (en cm)": "42", "Producto empaquetado: altura (en cm)": "4", "Producto empaquetado: profundidad (en cm)": "42", "Producto empaquetado: peso (en kg)": "1.5", "Marca": "MANTRA", "_source": "https://www.leroymerlin.es/productos/plafon-led-redondo-blanco-mantra-3850-lm-blanco-neutro-40-cm-ip20-97518316.html", "_images": ["/assets/img/productos/97518316.jpg", "/assets/img/productos/97518316_1.jpg", "/assets/img/productos/97518316_2.jpg", "/assets/img/productos/97518316_3.jpg", "/assets/img/productos/97518316_4.jpg", "/assets/img/productos/97518316_5.jpg", "/assets/img/productos/97518316_6.jpg", "/assets/img/productos/97518316_7.jpg"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/5293968/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "official", "label": "Documento 2", "url": "https://media.adeo.com/media/5146701/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-