	(263, '84844260', 'Downlight LED de superficie INSPIRE PP blanco redondo ø17 cm 1200 lm W luz blanco frío 6000K CRI 89-80 luz natural y fiel IP20 - Foco LED de superficie para techos', 'downlight-led-de-superficie-inspire-pp-blanco-redondo-17-cm-1200-lm-w-luz-blanco-frio-6000k-cri-89-8-a10b3c', 2, 51, 8.29, 21.0, 22, 'basic', 0, 'Downlight led redondo Inspire fabricado en aluminio con acabado en color blanco mate. Emite una luz blanca fría de 6.000 K con 1.600 lúmenes de intensidad. Es ideal para cualquier habitación excepto el baño el baño. Índice de protección: IP20 (uso en interior). Garantía de 5 años. Etiqueta energética: E. Medidas: 17 cm de diámetro.', '{"Diámetro (en cm)": "17", "Anchura (en cm)": "0", "Altura total (en mm)": "3.2", "Altura de empotrado (en cm)": "3.2", "Lugar de uso": "Interior", "Índice de protección (IP)": "IP20", "Intensidad luminosa (en lumen)": "1200", "Variación de la intensidad de la luz": "No", "Temperatura de color (en K)": "6000", "Color de la luz": "Blanco", "Color de la luz ajustable": "No", "Objeto conectado (domótica y smarthome)": "No", "Aspecto": "Mate", "Familia de color": "Blanco", "Forma": "Redondo", "Acabado del producto": "Arenado", "Marca del producto": "INSPIRE", "Especificidad del producto": "Producto sin características específicas", "Índice de reproducción cromática (IRC)": "De 80 a 84", "Peso neto (en kg)": "0.255", "Tipo de protocolo wifi": "El producto no es un dispositivo conectado (domótica y smarthome)", "Box domótico compatible": "El producto no necesita un Box", "Compatible con variador": "No", "Tipo de tecnología de la bombilla": "LED", "Producto empaquetado: anchura (en cm)": "17.5", "Producto empaquetado: altura (en cm)": "5", "Producto empaquetado: profundidad (en cm)": "17.5", "Producto empaquetado: peso (en kg)": "0.26", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/downlight-led-de-superficie-inspire-pp-blanco-redondo-17-cm-1200-lm-w-luz-blanco-frio-6000k-cri-89-80-luz-natural-y-fiel-ip20-foco-led-de-superficie-para-techos-84844260.html", "_images": ["/assets/img/productos/84844260.png", "/assets/img/productos/84844260_1.png", "/assets/img/productos/84844260_2.png", "/assets/img/productos/84844260_3.png", "/assets/img/productos/84844260_4.png"]}', '2026-05-06 22:42:44', '/assets/img/productos/84844260.png'),
	(264, '95494462', 'Plafón LED redondo Sanoa 3600 lm luz neutra 4000K ø30 cm IP20', 'plafon-led-redondo-sanoa-3600-lm-luz-neutra-4000k-30-cm-ip20-9a9b46', 2, 51, 31.99, 21.0, 94, 'basic', 0, 'Descubra el foco Sanoa, la solución ideal para una iluminación potente y personalizable sin necesidad de empotrar. Este foco de superficie, con un grosor ultrafino de 2 cm, incorpora tecnología LED integrada y reparable con clasificación energética C, lo que garantiza un bajo consumo. Además, cuenta con certificación IP44, lo que lo hace apto para espacios húmedos como baños. Antes de la instalación, puede seleccionar el color de luz deseado con el selector Kelvin integrado (2700 K cálido, 4000 K neutro o 6000 K frío). Además, ajuste fácilmente la intensidad entre el 100 % y el 50 % con su interruptor de pared estándar. El foco Sanoa está disponible en varios tamaños, redondos o cuadrados, y cuenta con varios acabados de marco: efecto madera, blanco, negro o níquel satinado. Invierta con confianza, sabiendo que su compra cuenta con una garantía de 7 años.', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "2700 | 4000 | 6000", "Variación de la intensidad de la luz": "Sí", "Color de la luz ajustable": "Sí", "Familia de color": "Gris / plata", "Aspecto": "Satinado", "Estilo internacional": "Design", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Altura (en cm)": "2", "Anchura (en cm)": "30", "Diámetro (en cm)": "30", "Peso neto (en kg)": "0.736", "Garantía (en años)": "7", "Clase energética (A a G)": "C", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "31", "Producto empaquetado: altura (en cm)": "2.8", "Producto empaquetado: profundidad (en cm)": "31", "Producto empaquetado: peso (en kg)": "0.8", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-led-redondo-sanoa-3600-lm-luz-neutra-4000k-30-cm-ip20-95494462.html", "_images": ["/assets/img/productos/95494462.png", "/assets/img/productos/95494462_1.png", "/assets/img/productos/95494462_2.png", "/assets/img/productos/95494462_3.png", "/assets/img/productos/95494462_4.png", "/assets/img/productos/95494462_5.png", "/assets/img/productos/95494462_6.png", "/assets/img/productos/95494462_7.png", "/assets/img/productos/95494462_8.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/5215982/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4386994/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 22:42:47', '/assets/img/productos/95494462.png'),
	(265, '86222787', 'Plafón LED Moon INSPIRE 12W blanco neutro', 'plafon-led-moon-inspire-12w-blanco-neutro-e1687f', 2, 51, 9.95, 21.0, 51, 'basic', 0, 'Plafón led Inspire Moon fabricado en metal y acrílico con acabado de color blanco. Los plafones son una interesante opción lumínica para colocar en los techos del hogar, sobre todo en habitaciones de espacios reducidos. Pueden aportar la misma intensidad de luz que una lámpara de colgar pero ocupando menos espacio, ya que quedan instalados a ras de techo. El plafón Moon cuenta con 1 luz, índice de protección IP21 (resistente a un goteo vertical de agua), 12 W de potencia y 220/240 V de tensión. Etiqueta energética: E. Medidas: 25 x 65 cm (ancho x alto).', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "4000", "Variación de la intensidad de la luz": "No", "Color de la luz ajustable": "No", "Familia de color": "Blanco", "Aspecto": "Mate", "Estilo internacional": "Essential", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Altura (en cm)": "6.5", "Anchura (en cm)": "25", "Diámetro (en cm)": "25", "Peso neto (en kg)": "0.225", "Garantía (en años)": "5", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "25.9", "Producto empaquetado: altura (en cm)": "7.2", "Producto empaquetado: profundidad (en cm)": "25.5", "Producto empaquetado: peso (en kg)": "0.393", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-led-moon-inspire-12w-blanco-neutro-86222787.html", "_images": ["/assets/img/productos/86222787.png", "/assets/img/productos/86222787_1.png", "/assets/img/productos/86222787_2.png", "/assets/img/productos/86222787_3.png", "/assets/img/productos/86222787_4.png", "/assets/img/productos/86222787_5.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4868094/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3585911/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/3570863/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 22:42:50', '/assets/img/productos/86222787.png'),
	(266, '91242437', 'Plafón Lano INSPIRE LED 1700 lm blanco neutro', 'plafon-lano-inspire-led-1700-lm-blanco-neutro-8024a0', 2, 51, 23.79, 21.0, 84, 'basic', 0, 'Plafón Inspire Lano con forma redonda y acabado de color negro. Cuenta con índice de protección IP44, 2300 lúmenes de flujo luminoso y 4000 K de temperatura de color, lo que se traduce en una luz de color blanco neutro. Ofrece 3 años de garantía. Medidas: 29 cm de diámetro.', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "4000", "Variación de la intensidad de la luz": "No", "Color de la luz ajustable": "No", "Familia de color": "Negro", "Aspecto": "Satinado", "Estilo internacional": "Design", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Altura (en cm)": "2.5", "Anchura (en cm)": "29", "Diámetro (en cm)": "29", "Peso neto (en kg)": "0.63", "Garantía (en años)": "5", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "31", "Producto empaquetado: altura (en cm)": "3", "Producto empaquetado: profundidad (en cm)": "31", "Producto empaquetado: peso (en kg)": "0.767", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-lano-inspire-led-1700-lm-blanco-neutro-91242437.html", "_images": ["/assets/img/productos/91242437.png", "/assets/img/productos/91242437_1.png", "/assets/img/productos/91242437_2.png", "/assets/img/productos/91242437_3.png", "/assets/img/productos/91242437_4.png", "/assets/img/productos/91242437_5.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/5203638/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}, {"type": "manual", "label": "Manual de instrucciones y reparabilidad", "url": "https://media.adeo.com/media/4446503/media.pdf", "size": null, "mime": "application/pdf", "source_host": "www.leroymerlin.es"}]}', '2026-05-06 22:42:54', '/assets/img/productos/91242437.png'),
	(267, '92403446', 'Plafón Piazo INSPIRE LED redondo 4000 lm madera 48 cm color cambiante', 'plafon-piazo-inspire-led-redondo-4000-lm-madera-48-cm-color-cambiante-0f6c93', 3, 51, 53.99, 21.0, 135, 'basic', 0, 'Plafón con fuente de luz Inspire modelo Piazo fabricado en hierro y acrílico. Color blanco. Cuenta con 1 luz, índice de protección IP20, 4000 lúmenes de flujo luminoso, módulo led y de 2700 a 6500 K de temperatura de color, lo que se traduce en una luz de color variable. Este producto es reparable y tiene una garantía de 5 años; ponte en contacto con el servicio posventa de tu tienda para obtener más detalles. Medidas: 48 x 7 x 48 cm (ancho x alto x fondo).', '{"Color de la luz": "Blanco", "Temperatura de color (en K)": "De 2700 a 6500", "Variación de la intensidad de la luz": "No", "Color de la luz ajustable": "No", "Familia de color": "Blanco", "Aspecto": "Mate", "Estilo internacional": "Nature", "Forma": "Redondo", "Contiene madera": "No", "Objeto conectado (domótica y smarthome)": "No", "Ángulo del haz de luz (en °)": "140", "Altura (en cm)": "7", "Anchura (en cm)": "48", "Diámetro (en cm)": "48", "Peso neto (en kg)": "1.53", "Garantía (en años)": "5", "Clase energética (A a G)": "D", "Marca del producto": "INSPIRE", "Producto empaquetado: anchura (en cm)": "49", "Producto empaquetado: altura (en cm)": "7.5", "Producto empaquetado: profundidad (en cm)": "48.5", "Producto empaquetado: peso (en kg)": "1.793", "Marca": "INSPIRE", "_source": "https://www.leroymerlin.es/productos/plafon-piazo-inspire-led-redondo-4000-lm-madera-48-cm-color-cambiante-92403446.html", "_images": ["/assets/img/productos/92403446.png", "/assets/img/productos/92403446_1.png", "/assets/img/productos/92403446_2.png", "/assets/img/productos/92403446_3.png", "/assets/img/productos/92403446_4.png", "/assets/img/productos/92403446_5.png", "/assets/img/productos/92403446_6.png", "/assets/img/productos/92403446_7.png"], "_documents": [{"type": "manual", "label": "Manual de instrucciones y rep