	(324, '96552916', 'Bombilla LED E27 inteligente compatibles con WIZ 13W 1521 lm RGB blanco regulable', 'bombilla-led-e27-inteligente-compatibles-con-wiz-13w-1521-lm-rgb-blanco-regulable-e17949', 3, 12, 13.99, 21.0, 149, 'basic', 0, 'Bombilla inteligente Philips Smart LED, equivalente 100W, 13W.E27. WIFI y Bluetooth.1521 lúmenes. RGB y regulable de cálido a fría ( 2700K-6500K).Regulable la cantidad de luz de 5% a 100%.', '{"Número de unidades consumidor": "1", "Intensidad luminosa (en lumen)": "1521", "Tipo de casquillo": "E27", "Tipo de producto": "Bombilla", "Tipo de bombilla": "Estándar | Inteligente", "Índice de protección (IP)": "IP20", "Potencia (en W)": "13", "Color de la luz": "Color cambiante", "Temperatura de color (en K)": "De 2700 a 6500", "Variación de la intensidad de la luz": "Sí", "Color de la luz ajustable": "Sí", "Objeto conectado (domótica y smarthome)": "Sí", "Vida útil (en h)": "15000", "Haz de la bombilla (ángulo) (en °)": "300", "Acabado del vidrio": "Opaco", "Compatible con variador": "Sí", "Material principal en la masa total del producto": "PVC", "Garantía (en años)": "3", "Clase energética (A a G)": "E", "Marca del producto": "PHILIPS", "Batería incluida": "No", "Mando a distancia incluido": "No", "Índice de reproducción cromática (IRC)": "De 80 a 89", "Tipo de protocolo wifi": "Bluetooth Zigbee", "Alimentación": "Red eléctrica", "Con luz ultravioleta (UV)": "No", "Especificidad del producto": "Control de la intensidad de la luz", "Tipo de tecnología de la bombilla": "LED", "Producto empaquetado: anchura (en cm)": "7", "Producto empaquetado: altura (en cm)": "16", "Producto empaquetado: profundidad (en cm)": "7", "Producto empaquetado: peso (en kg)": "0.11", "Marca": "PHILIPS", "_source": "https://www.leroymerlin.es/productos/bombilla-led-e27-inteligente-compatibles-con-wiz-13w-1521-lm-rgb-blanco-regulable-96552916.html", "_images": ["/assets/img/productos/96552916.jpg", "/assets/img/productos/96552916_1.jpg", "/assets/img/productos/965529