	(377, '85289801', 'Router Wi-Fi Móvil TP-Link M7010, WiFi, 300 Mbps, MIMO, 4G LTE, SIM, Batería 8 Horas', 'router-wi-fi-movil-tp-link-m7010-wifi-300-mbps-mimo-4g-lte-sim-bateria-8-horas-f7a422', 6, 38, 36.0, 21.0, 10, 'basic', 0, 'Router 4G Wi-Fi Mi-Fi M7010 LTE
