	(396, '93115207', 'Cámara de vigilancia exterior con panel solar NIVIAN', 'camara-de-vigilancia-exterior-con-panel-solar-nivian-b25e68', 8, 59, 56.99, 21.0, 76, 'basic', 0, 'Cámara a batería WiFi con panel solar incluido, ideal para vigilancia en exteriores sin cables, con carga autónoma y conectividad remota', '{"Tipo de producto": "Cámara de videovigilancia", "Motorizada": "Sí", "Escucha a distancia": "Sí, escucha y diálogo", "Visión nocturna (en m) )": "10", "Visualización en internet": "Sí", "Material principal en la masa total del producto": "PVC", "Micro integrado": "Sí", "Tipo de embalaje": "Caja", "Alcance del receptor en campo abierto": "10M", "Producto empaquetado: anchura (en cm)": "30", "Producto empaquetado: altura (en cm)": "20", "Producto empaquetado: profundidad (en cm)": "21", "Producto empaquetado: peso (en kg)": "2.2", "Marca": "NIVIAN", "_source": "https://www.leroymerlin.es/productos/camara-de-vigilancia-exterior-con-panel-solar-nivian-93115207.html"}', '2026-05-06 22:51:10', '/assets/img/productos/93115207.png'),
	(397, '89919643', 'Cámara de vigilancia exterior c/bateria y Panel Solar, IMOU Cell Go Kit', 'camara-de-vigilancia-exterior-cbateria-y-panel-solar-imou-cell-go-kit-5624f7', 8, 60, 44.99, 21.0, 9, 'basic', 0, 'Experimente una protección versátil con IMOU Cell Go Kit, una cámara de seguridad inalámbrica y resistente a la intemperie para uso en interiores y exteriores. 
