	(580, '16374624', 'Interruptor magnetotérmico CHINT 1P+N 10A', 'interruptor-magnetotermico-chint-1pn-10a-3fa139', 4, 16, 13.25, 21.0, 41, 'basic', 0, 'Interruptor magnetotérmico de 10 A, unipolar + neutro DPN. Ideado para la protección de la instalación eléctrica y aparatos, contra cortocircuitos y sobrecargas en instalaciones monofásicas o bifásicas.', '{"Intensidad (en A)": "10", "Marca del producto": "CHINT", "Tensión (en V)": "250", "Red eléctrica": "Fase + neutro", "Producto empaquetado: anchura (en cm)": "7", "Producto empaquetado: altura (en cm)": "1.5", "Producto empaquetado: profundidad (en cm)": "9", "Producto empaquetado: peso (en kg)": "0.112", "Subcategoría": "Magnetotérmicos", "Gama": "1P+N", "Intensidad nominal (A)": "10A", "_extra_intensidad": "10A", "Módulos": "1 módulo", "_extra_modulos": "1", "_source": "https://www.leroymerlin.es/productos/interruptor-magnetotermico-chint-1p-n-10a-16374624.html", "_images": ["/assets/img/productos/16374624.jpg"]}', '2026-05-10 00:56:19', '/assets/img/productos/16374624.jpg'),
	(581, '14787801', 'Interruptor NIESSEN Zenit blanco', 'interruptor-niessen-zenit-blanco-4d43e6', 1, 11, 3.86, 21.0, 104, 'basic', 0, 'Interruptor que permite apagar y encender la luz fabricado en aluminio de color blanco brillante. Lo podrás combinar con otros elementos de la serie Zenit, disponibles en Leroy Merlin, y crear un ambiente a tu gusto en las habitaciones de tu hogar. Cuenta con un sistema de seguridad infantil para evitar accidentes de los más pequeños. Medidas: 100 x 100 mm (ancho x alto).', '{"Nombre de la serie": "Zenit", "Tipo de producto": "Conmutador", "Marca del producto": "NIESSEN", "Familia de color": "Blanco", "Tipo de fijación": "Tornillo", "Anchura (en mm)": "100", "Altura (en mm)": "100", "Tipo de función": "Interruptor bipolar", "Objeto conectado (domótica y smarthome)": "No", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "10.8", "Producto empaquetado: altura (en cm)": "14.5", "Producto empaquetado: profundidad (en cm)": "5.1", "Producto empaquetado: peso (en kg)": "0.12", "Subcategoría": "Interruptores", "Gama": "Zenit", "_extra_color": "Blanco", "_extra_tipo": "Conmutador", "_source": "https://www.leroymerlin.es/productos/interruptor-niessen-zenit-blanco-14787801.html", "_images": ["/assets/img/productos/14787801.jpg", "/assets/img/productos/14787801_1.jpg", "/assets/img/productos/14787801_2.png", "/assets/img/productos/14787801_3.jpeg", "/assets/img/productos/14787801_4.jpeg"], "_variant_group": "niessen-zenit-interruptores-by-tipo-color-blanco", "_variant_axis": "Tipo", "_variant_default": "14787801", "_variant_is_default": "1", "_variant_label": "Conmutador", "_variants": [{"sku": "14787801", "label": "Conmutador", "price": 3.86}, {"sku": "14787815", "label": "Doble", "price": 6.92}]}', '2026-05-10 01:54:55', '/assets/img/productos/14787801.jpg'),
	(582, '96026206', 'Interruptor / conmutador con luz NIESSEN Zenit antracita', 'interruptor-conmutador-con-luz-niessen-zenit-antracita-d457ba', 1, 11, 17.99, 21.0, 140, 'basic', 0, 'Interruptor/conmutador Niessen Zenit con iluminación flowpack Antracita BN2202.31 AN', '{"Nombre de la serie": "Zenit", "Tipo de producto": "Conmutador", "Marca del producto": "NIESSEN", "Familia de color": "Antracita", "Acabado del producto": "Liso", "Tipo de fijación": "Tornillo", "Anchura (en mm)": "44", "Altura (en mm)": "44", "Tipo de función": "Interruptor bipolar", "Objeto conectado (domótica y smarthome)": "No", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "10", "Producto empaquetado: altura (en cm)": "4", "Producto empaquetado: profundidad (en cm)": "14", "Producto empaquetado: peso (en kg)": "0.03", "Subcategoría": "Interruptores", "Gama": "Zenit", "_extra_color": "Antracita", "_extra_tipo": "Conmutador", "_source": "https://www.leroymerlin.es/productos/interruptor-conmutador-con-luz-niessen-zenit-antracita-96026206.html", "_images": ["/assets/img/productos/96026206.jpg", "/assets/img/productos/96026206_1.png"]}', '2026-05-10 01:54:56', '/assets/img/productos/96026206.jpg'),
	(583, '82037059', 'Pack de interruptor y marco individual Zenit plata', 'pack-de-interruptor-y-marco-individual-zenit-plata-0cf525', 1, 11, 8.28, 21.0, 39, 'basic', 0, 'Pack de interruptor y marco en color plata brillante. Este interruptor puede combinarse con otro conmutador para encender y apagar desde dos puntos diferentes. Medidas: 100 x 100 mm (ancho x alto).', '{"Nombre de la serie": "Zenit", "Tipo de producto": "Conmutador", "Marca del producto": "NIESSEN", "Familia de color": "Plata", "Tipo de fijación": "Tornillo", "Anchura (en mm)": "85", "Altura (en mm)": "85", "Subcategoría": "Interruptores", "Gama": "Zenit", "_extra_color": "Plata", "_extra_tipo": "Conmutador", "_source": "https://www.leroymerlin.es/productos/pack-de-interruptor-y-marco-individual-zenit-plata-82037059.html", "_images": ["/assets/img/productos/82037059.png", "/assets/img/productos/82037059_1.jpg", "/assets/img/productos/82037059_2.jpg"], "_variant_group": "niessen-zenit-interruptores-by-tipo-color-plata", "_variant_axis": "Tipo", "_variant_default": "82037059", "_variant_is_default": "1", "_variant_label": "Conmutador", "_variants": [{"sku": "82037059", "label": "Conmutador", "price": 8.28}, {"sku": "82037060", "label": "Doble", "price": 13.22}]}', '2026-05-10 01:54:57', '/assets/img/productos/82037059.png'),
	(584, '14787815', 'Interruptor doble NIESSEN Zenit blanco', 'interruptor-doble-niessen-zenit-blanco-eb01b1', 1, 11, 6.92, 21.0, 143, 'basic', 0, 'Interruptor doble que permite apagar y encender la luz fabricado en aluminio de color blanco brillante. Lo podrás combinar con otros elementos de la serie Zenit, disponibles en Leroy Merlin, y crear un ambiente a tu gusto en las habitaciones de tu hogar. Cuenta con un sistema de seguridad infantil para evitar accidentes de los más pequeños. Medidas: 100 x 100 mm (ancho x alto).', '{"Nombre de la serie": "Zenit", "Tipo de producto": "Doble", "Marca del producto": "NIESSEN", "Familia de color": "Blanco", "Tipo de fijación": "Tornillo", "Anchura (en mm)": "100", "Altura (en mm)": "100", "Tipo de función": "Interruptor bipolar", "Objeto conectado (domótica y smarthome)": "No", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "9.5", "Producto empaquetado: altura (en cm)": "11.5", "Producto empaquetado: profundidad (en cm)": "4", "Producto empaquetado: peso (en kg)": "0.08", "Subcategoría": "Interruptores", "Gama": "Zenit", "_extra_color": "Blanco", "_extra_tipo": "Doble", "_source": "https://www.leroymerlin.es/productos/interruptor-doble-niessen-zenit-blanco-14787815.html", "_images": ["/assets/img/productos/14787815.jpg", "/assets/img/productos/14787815_1.png", "/assets/img/productos/14787815_2.jpeg", "/assets/img/productos/14787815_3.jpeg"], "_variant_group": "niessen-zenit-interruptores-by-tipo-color-blanco", "_variant_axis": "Tipo", "_variant_default": "14787801", "_variant_is_default": "0", "_variant_label": "Doble", "_variants": [{"sku": "14787801", "label": "Conmutador", "price": 3.86}, {"sku": "14787815", "label": "Doble", "price": 6.92}]}', '2026-05-10 01:54:58', '/assets/img/productos/14787815.jpg'),
	(585, '82037060', 'Pack de interruptor y marco doble Zenit plata', 'pack-de-interruptor-y-marco-doble-zenit-plata-a668ea', 1, 11, 13.22, 21.0, 84, 'basic', 0, 'Pack de interruptor y marco en color plata brillante. Este interruptor permite encender y apagar desde un único mecanismo dos puntos de luz independiente. Medidas: 100 x 100 mm (ancho x alto).', '{"Nombre de la serie": "Zenit", "Tipo de producto": "Doble", "Marca del producto": "NIESSEN", "Familia de color": "Plata", "Tipo de fijación": "Tornillo", "Anchura (en mm)": "85", "Altura (en mm)": "85", "Subcategoría": "Interruptores", "Gama": "Zenit", "_extra_color": "Plata", "_extra_tipo": "Doble", "_source": "https://www.leroymerlin.es/productos/pack-de-interruptor-y-marco-doble-zenit-plata-82037060.html", "_images": ["/assets/img/productos/82037060.png", "/assets/img/productos/82037060_1.jpg", "/assets/img/productos/82037060_2.jpg"], "_variant_group": "niessen-zenit-interruptores-by-tipo-color-plata", "_variant_axis": "Tipo", "_variant_default": "82037059", "_variant_is_default": "0", "_variant_label": "Doble", "_variants": [{"sku": "82037059", "label": "Conmutador", "price": 8.28}, {"sku": "82037060", "label": "Doble", "price": 13.22}]}', '2026-05-10 01:55:00', '/assets/img/productos/82037060.png'),
	(586, '85164195', 'Enchufe con toma de tierra SIMON 270 negro mate', 'enchufe-con-toma-de-tierra-simon-270-negro-mate-e22974', 1, 1, 6.49, 21.0, 98, 'basic', 0, 'Dale forma, energía y funcionalidad a tus espacios con el enchufe Schuko de la serie Simon 270. Una solución compacta y precisa que une diseño, fiabilidad y facilidad de instalación en una sola pieza. Con una toma de corriente de 16 A y 250 V~ y conexión por tornillo, está preparado para funcionar en todo tipo de ambientes interiores, aportando una base segura y duradera para tu día a día.
Su estética negra mate y su formato cuadrado se integran con naturalidad en cualquier entorno, sin romper la armonía visual ni sobrecargar el espacio. Gracias a su compatibilidad con marcos Simon 270 y cajas de empotrar universales, permite composiciones limpias, sobrias y perfectamente alineadas. Una pieza técnica que suma discreción, orden y continuidad visual al conjunto.
Instalarlo es tan sencillo como intuitivo: basta con fijarlo y conectar los cables de 1,5 a 2,5 mm² para que todo encaje. Sin herramientas específicas, sin instrucciones complejas, sin esfuerzo. ¿Y el mantenimiento? Solo un paño ', '{"Nombre de la serie": "270", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo", "Altura (en mm)": "55", "Anchura (en mm)": "55", "Profundidad (en mm)": "41", "Marca del producto": "SIMON", "Modelo comercial": "Simon 270", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "5", "Producto empaquetado: altura (en cm)": "5.5", "Producto empaquetado: profundidad (en cm)": "5.5", "Producto empaquetado: peso (en kg)": "0.05", "Subcategoría": "Enchufes", "Gama": "Serie 270", "Familia de color": "Negro", "_extra_color": "Negro", "_source": "https://www.leroymerlin.es/productos/enchufe-con-toma-de-tierra-simon-270-negro-mate-85164195.html", "_images": ["/assets/img/productos/85164195.jpg", "/assets/img/productos/85164195_1.jpg", "/assets/img/productos/85164195_2.jpg", "/assets/img/productos/85164195_3.jpg", "/assets/img/productos/85164195_4.png"], "_variant_group": "simon-serie-270-enchufes-by-color", "_variant_axis": "Color", "_variant_default": "85164181", "_variant_is_default": "0", "_variant_label": "Negro", "_variants": [{"sku": "85164181", "label": "Blanco", "price": 4.39}, {"sku": "85164195", "label": "Negro", "price": 6.49}, {"sku": "83411570", "label": "Bronce", "price": 14.79}]}', '2026-05-10 01:55:01', '/assets/img/productos/85164195.jpg'),
	(587, '83411570', 'Enchufe CLEAN con toma de tierra SIMON 270 color oro', 'enchufe-clean-con-toma-de-tierra-simon-270-color-oro-398ad7', 1, 1, 14.79, 21.0, 95, 'basic', 0, 'Toma de enchufe Clean con toma de tierra y protección infantil. La base del enchufe queda totalmente enrasada cuando no tiene un elemento conectado. Diseño decorativo de fácil limpieza. El sistema de embornamiento es a tornillo, asegurando una correcta instalación. Pertenece a la serie Simon 270, con un completo surtido de mecanismos para combinar con este producto, tanto mecánicos como conectivos a través de la red wifi.', '{"Nombre de la serie": "270", "Tipo de producto": "Toma de alimentación", "Tipo de fijación": "Tornillo", "Altura (en mm)": "55", "Anchura (en mm)": "55", "Profundidad (en mm)": "41", "Marca del producto": "SIMON", "Modelo comercial": "Simon 270", "Material principal en la masa total del producto": "Policarbonato", "Garantía (en años)": "3", "Producto empaquetado: anchura (en cm)": "5.5", "Producto empaquetado: altura (en cm)": "5.3", "Producto empaquetado: profundidad (en cm)": "4.7", "Producto empaquetado: peso (en kg)": "0.054", "Subcategoría": "Enchufes", "Gama": "Serie 270", "Familia de color": "Bronce", "_extra_color": "Bronce", "_source": "https://www.leroymerlin.es/productos/enchufe-clean-con-toma-de-tierra-simon-270-color-oro-83411570.html", "_images": ["/assets/img/productos/83411570.jpg", "/assets/img/productos/83411570_1.jpg", "/assets/img/productos/83411570_2.jpg", "/assets/img/productos/83411570_3.png", "/assets/img/productos/83411570_4.png"], "_variant_group": "simon-serie-270-enchufes-by-color", "_variant_axis": "Color", "_variant_default": "85164181", "_variant_is_default": "0", "_variant_label": "Bronce", "_variants": [{"sku": "85164181", "label": "Blanco", "price": 4.39}, {"sku": "85164195", "label": "Negro", "price": 6.49}, {"sku": "83411570", "label": "Bronce", "price": 14.79}]}', '2026-05-10 01:55:02', '/assets/img/productos/83411570.jpg'),
